import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

class FastScanner(private val reader: BufferedReader) {
    private var tokenizer: StringTokenizer = StringTokenizer("")

    fun next(): String {
        while (!tokenizer.hasMoreTokens()) {
            val line = reader.readLine() ?: return ""
            tokenizer = StringTokenizer(line)
        }
        return tokenizer.nextToken()
    }

    fun nextInt(): Int = next().toInt()
    fun nextLong(): Long = next().toLong()
}

class Myon {
    private val cin: FastScanner
    private val dp: LongArray
    private var a: Int = 0
    private var b: Long = 0
    private var c: Char = '.'

    private val f0 = "What are you doing at the end of the world? Are you busy? Will you save us?"
    private val s0 = "What are you doing while sending \""
    private val s1 = "\"? Are you busy? Will you send \""
    private val s2 = "\"?"

    private val MAX = 100005
    private val MAX2 = 1e18 + 10

    init {
        cin = FastScanner(BufferedReader(InputStreamReader(System.`in`)))
        dp = LongArray(MAX)
        dp[0] = f0.length.toLong()
        for (i in 1 until MAX) {
            if (dp[i - 1] > MAX2 / 2) {
                dp[i] = MAX2.toLong()
            } else {
                dp[i] = dp[i - 1] * 2 + s0.length + s1.length + s2.length
            }
        }
    }

    fun calc() {
        val N = cin.nextInt()
        val sb = StringBuilder()
        for (i in 0 until N) {
            a = cin.nextInt()
            b = cin.nextLong() - 1
            while (a != -1) {
                dfs()
            }
            sb.append(c)
        }
        println(sb.toString())
    }

    private fun dfs() {
        if (b >= dp[a]) {
            c = '.'
            a = -1
            return
        }
        if (a == 0) {
            c = f0[b.toInt()]
            a = -1
            return
        }
        if (b < s0.length) {
            c = s0[b.toInt()]
            a = -1
            return
        }
        b -= s0.length
        if (b < dp[a - 1]) {
            a--
            return
        }
        b -= dp[a - 1]
        if (b < s1.length) {
            c = s1[b.toInt()]
            a = -1
            return
        }
        b -= s1.length
        if (b < dp[a - 1]) {
            a--
            return
        }
        b -= dp[a - 1]
        c = s2[b.toInt()]
        a = -1
    }
}

fun main() {
    Myon().calc()
}

